namespace FluentSnap;
public static class CaptureService
{
 public static System.Drawing.Rectangle VirtualBounds => System.Windows.Forms.SystemInformation.VirtualScreen;
 public static BitmapSource Capture(System.Drawing.Rectangle bounds){var virtualBounds=VirtualBounds;var clipped=System.Drawing.Rectangle.Intersect(bounds,virtualBounds);if(clipped.Width<1||clipped.Height<1)throw new InvalidOperationException("The selected area is no longer available.");using var bitmap=new System.Drawing.Bitmap(clipped.Width,clipped.Height,System.Drawing.Imaging.PixelFormat.Format32bppArgb);using(var g=System.Drawing.Graphics.FromImage(bitmap))g.CopyFromScreen(clipped.Left,clipped.Top,0,0,bitmap.Size,System.Drawing.CopyPixelOperation.SourceCopy);return ToBitmapSource(bitmap);}
 public static BitmapSource CapturePolygon(IReadOnlyList<System.Drawing.Point> polygon){var minX=polygon.Min(p=>p.X);var minY=polygon.Min(p=>p.Y);var maxX=polygon.Max(p=>p.X);var maxY=polygon.Max(p=>p.Y);var bounds=System.Drawing.Rectangle.Intersect(System.Drawing.Rectangle.FromLTRB(minX,minY,maxX+1,maxY+1),VirtualBounds);if(bounds.Width<1||bounds.Height<1)throw new InvalidOperationException("The selected area is no longer available.");using var source=new System.Drawing.Bitmap(bounds.Width,bounds.Height,System.Drawing.Imaging.PixelFormat.Format32bppArgb);using(var g=System.Drawing.Graphics.FromImage(source))g.CopyFromScreen(bounds.Left,bounds.Top,0,0,source.Size,System.Drawing.CopyPixelOperation.SourceCopy);using var masked=new System.Drawing.Bitmap(bounds.Width,bounds.Height,System.Drawing.Imaging.PixelFormat.Format32bppArgb);using(var g=System.Drawing.Graphics.FromImage(masked)){g.Clear(System.Drawing.Color.Transparent);using var path=new System.Drawing.Drawing2D.GraphicsPath();path.AddPolygon(polygon.Select(p=>new System.Drawing.Point(p.X-bounds.Left,p.Y-bounds.Top)).ToArray());g.SetClip(path);g.DrawImageUnscaled(source,0,0);}return ToBitmapSource(masked);}
 static BitmapSource ToBitmapSource(System.Drawing.Bitmap bitmap){using var stream=new MemoryStream();bitmap.Save(stream,System.Drawing.Imaging.ImageFormat.Png);stream.Position=0;var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();image.Freeze();return image;}
}
